// Generado a partir de Natural Earth (world-atlas, land-110m). Proyección equirectangular del mundo entero.
export const MAPA = { lon0: -180, lat1: 80, k: 4.444444, ancho: 1600, alto: 613 };

/** Convierte [lat, lon] a coordenadas del viewBox del mapa. */
export function proyectar(lat: number, lon: number): [number, number] {
  return [(lon - MAPA.lon0) * MAPA.k, (MAPA.lat1 - lat) * MAPA.k];
}

